    paddle := scene.sprite("paddle", "assets/paddle.png").at(480.0, 500.0)
    ball := scene.circle("ball", radius: 8.0).at(480.0, 420.0)
    ball.velocity = Vec2.{ x: 220.0, y: -180.0 }

    scene.on_frame((frame) => {
        paddle.x = 480.0 + frame.input.axis(.Horizontal) * 360.0
        ball.move(ball.velocity * frame.seconds)

