//   winner: 7
//   committed        <-- cancelled task still committed the ledger
//   ledger closed
//   group done
//
// To make it safe under A the author must hand-write the check on every path:
fn transfer() -> Int {
    ledger :: open_ledger()
    time.sleep(200)
